//! `versions.lock`: one pinned download per line.

use std::fs;
use std::path::{Path, PathBuf};

use crate::Error;

const LOCK_HEADER: &str = "# Generated by `bazel run //tools/scripts/bootstrap/lock` from versions.toml.\n\
                           # Do not edit. Columns: component, platform, SHA-256, URL.\n";

/// One line of `versions.lock`.
pub struct Pin {
    pub component: String,
    /// A platform name, or `any` for files every platform installs.
    pub platform: String,
    pub sha256: String,
    pub url: String,
}

impl Pin {
    pub fn new(component: &str, platform: &str, sha256: String, url: String) -> Self {
        Pin {
            component: component.to_owned(),
            platform: platform.to_owned(),
            sha256,
            url,
        }
    }
}

pub fn write_lock(dir: &Path, pins: &[Pin]) -> Result<PathBuf, Error> {
    let mut lock = String::from(LOCK_HEADER);
    for pin in pins {
        lock.push_str(&format!(
            "{} {} {} {}\n",
            pin.component, pin.platform, pin.sha256, pin.url
        ));
    }
    let path = dir.join("versions.lock");
    fs::write(&path, lock).map_err(|source| Error::Write {
        path: path.clone(),
        source,
    })?;
    Ok(path)
}
